class Solution {
public:
    int numComponents(ListNode* head, vector<int>& nums) {
        unordered_set<int> s(nums.begin(), nums.end());
        int count = 0;
        bool prevIn = false;
        for (ListNode* cur = head; cur; cur = cur->next) {
            bool curIn = s.count(cur->val);
            if (curIn && !prevIn) {
                count++;
            }
            prevIn = curIn;
        }
        return count;
    }
};
